                if (!inside_tag) {
                    ss << "<em>";
                    inside_tag = true;
                }
                break;
            case '^':
                if (inside_tag) {
                    ss << "</em>";
                    inside_tag = false;
                }
                break;
            default:
                if (inside_tag) {
                    ss << c;
                    ss << "</em>";
                    inside_tag = false;
                } else {
                    ss << c;
